import os, re, sys

if len(sys.argv) < 2:
    print("usage: gen_camel.py <scratchpad-dir>")
    sys.exit(1)
SCRATCH = sys.argv[1]
QTGEN = os.path.join(SCRATCH, "qtgen/include")
QTBASE = os.path.join(SCRATCH, "qtbase")

# Only a REAL definition: class/struct NAME optionally followed by a base-class
# list, ending in '{' on the same or a continuation line -- never a bare
# forward declaration ('class Foo;'), which appears for the same name in many
# unrelated files and must never win over the file that actually defines it.
# A 'template <...>' line immediately before class/struct is skipped over --
# template classes (class QVarLengthArray, ...) split the template<> and
# class keywords across two lines as often as not.
cls_pat = re.compile(r'^\s*(?:class|struct)\s+(?:Q_[A-Z0-9_]*EXPORT\s+)?([A-Z][A-Za-z0-9_]*)')
fwd_pat = re.compile(r'^\s*(?:class|struct)\s+(?:Q_[A-Z0-9_]*EXPORT\s+)?([A-Z][A-Za-z0-9_]*)\s*;')
typedef_pat = re.compile(r'^\s*using\s+([A-Z][A-Za-z0-9_]*)\s*=')
template_pat = re.compile(r'^\s*template\s*<')

def scan(basedir, module):
    outdir = os.path.join(QTGEN, module)
    real = {}    # name -> header basename, from an actual definition
    weak = {}    # name -> header basename, from a bare forward declaration
    for root, dirs, files in os.walk(basedir):
        # 3rdparty headers are not Qt classes; doc/ holds documentation snippets whose
        # example classes (viewer.h defines its own QLabel, ...) would shadow the real ones.
        if '3rdparty' in root or '/doc' in root:
            continue
        for fn in files:
            if not fn.endswith('.h'):
                continue
            path = os.path.join(root, fn)
            try:
                with open(path, 'r', errors='ignore') as f:
                    lines = f.readlines()
            except IOError:
                continue
            i = 0
            n = len(lines)
            while i < n:
                line = lines[i]
                if template_pat.match(line):
                    # skip to the matching '>' (may span several lines for
                    # nested template parameter lists), then re-check the
                    # class/struct line right after it.
                    depth = line.count('<') - line.count('>')
                    j = i + 1
                    while depth > 0 and j < n:
                        depth += lines[j].count('<') - lines[j].count('>')
                        j += 1
                    i = j
                    if i >= n:
                        break
                    line = lines[i]

                m = cls_pat.match(line)
                if m and not fwd_pat.match(line):
                    name = m.group(1)
                    # find the '{' -- same line, or scan forward a few lines
                    # past a base-class list (': public Foo, private Bar')
                    k = i
                    found_brace = '{' in line
                    while not found_brace and k + 1 < n and k < i + 20:
                        k += 1
                        stripped = lines[k].lstrip()
                        if stripped.startswith('#'):
                            continue  # preprocessor conditionals in a base-class list
                        if ';' in lines[k] and '{' not in lines[k]:
                            break
                        if '{' in lines[k]:
                            found_brace = True
                    if found_brace and len(name) >= 2 and name[1].isupper():
                        real.setdefault(name, fn)
                    i += 1
                    continue

                m = typedef_pat.match(line)
                if m:
                    name = m.group(1)
                    if len(name) >= 2 and name[1].isupper():
                        real.setdefault(name, fn)
                    i += 1
                    continue

                m = fwd_pat.match(line)
                if m:
                    name = m.group(1)
                    if len(name) >= 2 and name[1].isupper():
                        weak.setdefault(name, fn)
                i += 1
    return outdir, real, weak

# Self-heal: forwards generated by an older run of this script from documentation snippets
# point (through the symlink farm) into a doc/ directory; drop them so they cannot win.
for mod in ("QtCore", "QtGui", "QtWidgets"):
    d = os.path.join(QTGEN, mod)
    if not os.path.isdir(d):
        continue
    for fn in os.listdir(d):
        p = os.path.join(d, fn)
        if os.path.islink(p) or '.' in fn or not os.path.isfile(p):
            continue
        try:
            m = re.match(r'#include "([^"]+)"', open(p).read())
        except (IOError, UnicodeDecodeError):
            continue
        if m and '/doc/' in os.path.realpath(os.path.join(d, m.group(1))):
            os.remove(p)

mods = [scan(os.path.join(QTBASE, "src/corelib"), "QtCore"),
        scan(os.path.join(QTBASE, "src/gui"), "QtGui"),
        scan(os.path.join(QTBASE, "src/widgets"), "QtWidgets")]
# A bare forward declaration ("class QApplication;" in gui's qwindowdefs.h) only earns a forward
# header if NO module defines the class for real; otherwise it would shadow the real one,
# since the module include directories are searched in order (QtGui before QtWidgets).
defined_somewhere = set()
for _, real, _ in mods:
    defined_somewhere.update(real)
counts = []
for outdir, real, weak in mods:
    weak = {n: f for n, f in weak.items() if n not in defined_somewhere}
    count = 0
    for name, fn in {**weak, **real}.items():
        with open(os.path.join(outdir, name), 'w') as out:
            out.write('#include "%s"\n' % fn)
        count += 1
    counts.append(count)
# stale weak forwards from older runs of this script that are now shadowing a real definition
for outdir, real, weak in mods:
    for name in list(weak):
        p = os.path.join(outdir, name)
        if name in defined_somewhere and name not in real and os.path.isfile(p) and not os.path.islink(p):
            os.remove(p)
print("QtCore forwards: %d, QtGui forwards: %d, QtWidgets forwards: %d" % tuple(counts))
